import {
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Section,
  Row,
  Column,
  Text,
  Img,
} from "jsx-email";
import { Fragment } from "react";
import type { ReactNode } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type CardsTimeline_CardsTimelineVariant =
  | "default"
  | "with-badge"
  | "with-accent"
  | "image-top"
  | "image-bottom";

interface CardsTimeline_CardsTimelineProps {
  theme?: EmailTheme;
  variant?: CardsTimeline_CardsTimelineVariant;
  date?: string;
  badge?: string;
  title?: string;
  description?: string;
  imageSrc?: string;
  imageAlt?: string;
}

const CardsTimeline_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const CardsTimeline_textStyle = {
  fontFamily: CardsTimeline_fontFamily,
  margin: 0,
} as const;

const CardsTimeline_CardsTimelineSection = (
  props: Omit<CardsTimeline_CardsTimelineProps, "theme">
) => {
  const { badge, date, description, imageAlt, imageSrc, title, variant } = {
    badge: "Today",
    date: "Monday",
    description: "Description of event",
    imageAlt: "One workspace. Every team.",
    imageSrc: emailAsset("timelines/cards.jpg"),
    title: "Miles traveled",
    variant: "default",
    ...props,
  };
  const dark =
    variant === "with-accent" ||
    variant === "image-top" ||
    variant === "image-bottom";
  const withBadge = variant !== "default";
  const withCheck = variant === "with-accent";
  const imageTop = variant === "image-top";
  const imageBottom = variant === "image-bottom";
  let cardBackgroundColor = "#fffffe";
  if (dark) {
    cardBackgroundColor = "#030712";
  } else if (variant === "with-badge") {
    cardBackgroundColor = "#f9fafb";
  }
  const image = (
    <Img
      alt={imageAlt}
      src={imageSrc}
      style={{
        borderRadius: "4px",
        maxWidth: "100%",
        verticalAlign: "middle",
      }}
      width="536"
    />
  );
  return (
    <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: "#fffffe",
              maxWidth: "100%",
              padding: variant === "default" ? 0 : "16px 0",
              width: "600px",
            }}
          >
            <Section style={{ width: "100%" }}>
              <Fragment>
                <Row>
                  <Column style={{ padding: "0 16px" }}>
                    <Section style={{ width: "100%" }}>
                      <Fragment>
                        <Row>
                          <Column
                            style={{
                              backgroundColor: cardBackgroundColor,
                              borderRadius:
                                variant === "default" ? undefined : "8px",
                              padding: "16px",
                            }}
                          >
                            {imageTop ? (
                              <>
                                {image}
                                <Section style={{ lineHeight: "16px" }}>
                                  &zwj;
                                </Section>
                              </>
                            ) : null}
                            <Section style={{ width: "100%" }}>
                              <Fragment>
                                <Row>
                                  <Column>
                                    <Section>
                                      <Fragment>
                                        <Row>
                                          <Column>
                                            <Section
                                              style={{
                                                backgroundColor:
                                                  variant === "default"
                                                    ? "#fcd34d"
                                                    : "#6ee7b7",
                                                borderRadius: "9999px",
                                                height: "12px",
                                                lineHeight: withCheck
                                                  ? "10px"
                                                  : "12px",
                                                textAlign: "center",
                                                width: "12px",
                                              }}
                                            >
                                              {withCheck ? (
                                                <Img
                                                  alt=""
                                                  src={emailAsset(
                                                    "timelines/icon-check.png"
                                                  )}
                                                  style={{
                                                    marginBottom: "1px",
                                                  }}
                                                  width="8"
                                                />
                                              ) : (
                                                <>&zwj;</>
                                              )}
                                            </Section>
                                          </Column>
                                          <Column style={{ width: "8px" }}>
                                            &zwj;
                                          </Column>
                                          <Column>
                                            <Text
                                              style={{
                                                ...CardsTimeline_textStyle,
                                                color: dark
                                                  ? "#e5e7eb"
                                                  : "#374151",
                                                fontSize: "12px",
                                                lineHeight: "16px",
                                              }}
                                            >
                                              {date}
                                            </Text>
                                          </Column>
                                        </Row>
                                      </Fragment>
                                    </Section>
                                  </Column>
                                  <Column style={{ textAlign: "right" }}>
                                    {withBadge ? (
                                      <span
                                        style={{
                                          backgroundColor: "#eef2ff",
                                          border: "1px solid #c7d2fe",
                                          borderRadius: "9999px",
                                          color: "#4f46e5",
                                          display: "inline-block",
                                          fontFamily: CardsTimeline_fontFamily,
                                          fontSize: "12px",
                                          fontWeight: 500,
                                          lineHeight: "16px",
                                          padding: "1px 8px",
                                        }}
                                      >
                                        {badge}
                                      </span>
                                    ) : null}
                                  </Column>
                                </Row>
                              </Fragment>
                            </Section>
                            <Text
                              style={{
                                ...CardsTimeline_textStyle,
                                color: dark ? "#fffffe" : "#030712",
                                fontSize: "18px",
                                fontWeight: 600,
                                lineHeight: "28px",
                                marginTop: "4px",
                              }}
                            >
                              {title}
                            </Text>
                            <Text
                              style={{
                                ...CardsTimeline_textStyle,
                                color: dark ? "#d1d5db" : "#4b5563",
                                fontSize: "16px",
                                lineHeight: "24px",
                                marginTop: "4px",
                              }}
                            >
                              {description}
                            </Text>
                            {imageBottom ? (
                              <>
                                <Section style={{ lineHeight: "16px" }}>
                                  &zwj;
                                </Section>
                                {image}
                              </>
                            ) : null}
                          </Column>
                        </Row>
                      </Fragment>
                    </Section>
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

const CardsTimeline_CardsTimeline = ({
  theme = defaultTheme,
  ...props
}: CardsTimeline_CardsTimelineProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Miles traveled</Preview>
    <EmailTailwind theme={theme}>
      <Body className="m-0">
        <CardsTimeline_CardsTimelineSection {...props} />
      </Body>
    </EmailTailwind>
  </Html>
);

CardsTimeline_CardsTimeline.PreviewProps = {
  theme: defaultTheme,
  variant: "default",
} satisfies CardsTimeline_CardsTimelineProps;

const __CardsTimeline = CardsTimeline_CardsTimeline;

type Changelog_ChangelogVariant =
  | "muted-left"
  | "muted-right"
  | "basic-left"
  | "basic-right"
  | "accent-left"
  | "accent-right";

type Changelog_ChangelogLayout = "line" | "boxed";

interface Changelog_ChangelogProps {
  theme?: EmailTheme;
  variant?: Changelog_ChangelogVariant;
  layout?: Changelog_ChangelogLayout;
  version?: string;
  date?: string;
  category?: string;
  title?: string;
  description?: string;
}

const Changelog_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const Changelog_responsiveStyles = `
    .changelog-mobile { display: none; }
    @media only screen and (max-width: 599px) {
      .changelog-meta { width: 96px !important; }
    }
    @media only screen and (max-width: 430px) {
      .changelog-meta, .changelog-gap { display: none !important; }
      .changelog-mobile { display: block !important; }
      .changelog-content { width: 100% !important; }
      .changelog-copy { text-align: left !important; }
    }
  `;

const Changelog_textStyle = {
  fontFamily: Changelog_fontFamily,
  margin: 0,
} as const;

const Changelog_ChangelogShell = ({ children }: { children: ReactNode }) => (
  <>
    <style>{Changelog_responsiveStyles}</style>
    <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: "#fffffe",
              maxWidth: "100%",
              width: "600px",
            }}
          >
            {children}
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  </>
);

interface Changelog_BadgeProps {
  muted: boolean;
  version: string;
}

const Changelog_VersionBadge = ({ muted, version }: Changelog_BadgeProps) => (
  <span
    style={{
      backgroundColor: muted ? "#f9fafb" : "#eef2ff",
      border: `1px solid ${muted ? "#d1d5db" : "#a5b4fc"}`,
      borderRadius: "9999px",
      color: muted ? "#4b5563" : "#4f46e5",
      display: "inline-block",
      fontFamily: Changelog_fontFamily,
      fontSize: "12px",
      fontWeight: 500,
      lineHeight: "16px",
      padding: "2px 8px",
    }}
  >
    {version}
  </span>
);

interface Changelog_MetaProps {
  category: string;
  date: string;
  muted: boolean;
  right: boolean;
  version: string;
}

const Changelog_ChangelogMeta = ({
  category,
  date,
  muted,
  right,
  version,
}: Changelog_MetaProps) => (
  <Column
    className="changelog-meta"
    style={{
      textAlign: right ? "left" : "right",
      verticalAlign: "top",
      width: "136px",
    }}
  >
    <Section style={{ lineHeight: "6px" }}>&zwj;</Section>
    <Changelog_VersionBadge muted={muted} version={version} />
    <Text
      style={{
        ...Changelog_textStyle,
        color: "#030712",
        fontSize: "16px",
        fontWeight: 600,
        lineHeight: "24px",
        marginTop: "8px",
      }}
    >
      {date}
    </Text>
    <Text
      style={{
        ...Changelog_textStyle,
        color: "#6b7280",
        fontSize: "12px",
        fontWeight: 600,
        lineHeight: "16px",
        marginTop: "8px",
      }}
    >
      {category}
    </Text>
  </Column>
);

const Changelog_ChangelogRail = ({
  muted,
  accent,
}: {
  accent: boolean;
  muted: boolean;
}) => (
  <Column style={{ verticalAlign: "top", width: "12px" }}>
    <Section
      style={{
        backgroundColor: muted ? undefined : "#4f46e5",
        border: muted ? "2px solid #d1d5db" : undefined,
        borderRadius: "9999px",
        height: muted ? "8px" : "12px",
        margin: muted ? "8px 2px 0" : "6px 0 0",
        width: muted ? "8px" : "12px",
      }}
    >
      &zwj;
    </Section>
    <Section
      style={{
        backgroundColor: accent ? "#030712" : "#d1d5db",
        height: "104px",
        margin: "0 auto",
        width: "2px",
      }}
    >
      &zwj;
    </Section>
  </Column>
);

interface Changelog_CopyProps {
  boxed: boolean;
  dark: boolean;
  description: string;
  title: string;
}

const Changelog_ChangelogCopy = ({
  boxed,
  dark,
  description,
  title,
}: Changelog_CopyProps) =>
  (() => {
    if (boxed) {
      return (
        <Section
          style={{
            backgroundColor: dark ? "#030712" : "#f9fafb",
            borderRadius: "8px",
            width: "100%",
          }}
        >
          <Fragment>
            <Row>
              <Column style={{ padding: "24px 24px 0" }}>
                <Text
                  style={{
                    ...Changelog_textStyle,
                    color: dark ? "#fffffe" : "#030712",
                    fontSize: "18px",
                    fontWeight: 600,
                    lineHeight: "24px",
                  }}
                >
                  {title}
                </Text>
              </Column>
            </Row>
            <Row>
              <Column style={{ padding: "16px 24px 24px" }}>
                <Text
                  style={{
                    ...Changelog_textStyle,
                    color: dark ? "#d1d5db" : "#4b5563",
                    fontSize: "16px",
                    lineHeight: "24px",
                  }}
                >
                  {description}
                </Text>
              </Column>
            </Row>
          </Fragment>
        </Section>
      );
    }
    return (
      <>
        <Text
          style={{
            ...Changelog_textStyle,
            color: "#030712",
            fontSize: "18px",
            fontWeight: 600,
            lineHeight: "24px",
          }}
        >
          {title}
        </Text>
        <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
        <Text
          style={{
            ...Changelog_textStyle,
            color: "#4b5563",
            fontSize: "16px",
            lineHeight: "24px",
          }}
        >
          {description}
        </Text>
      </>
    );
  })();

interface Changelog_ContentProps {
  accent: boolean;
  boxed: boolean;
  category: string;
  date: string;
  description: string;
  muted: boolean;
  right: boolean;
  title: string;
  version: string;
}

const Changelog_ChangelogContent = ({
  accent,
  boxed,
  category,
  date,
  description,
  muted,
  right,
  title,
  version,
}: Changelog_ContentProps) => {
  const copy = (
    <Column
      className="changelog-copy"
      style={{ paddingBottom: "80px", textAlign: right ? "right" : "left" }}
    >
      <Section className="changelog-mobile">
        <Changelog_VersionBadge muted={muted} version={version} />
        <Text
          style={{
            ...Changelog_textStyle,
            color: "#030712",
            fontSize: "16px",
            fontWeight: 600,
            lineHeight: "24px",
            marginTop: "8px",
          }}
        >
          {date}
        </Text>
        <Text
          style={{
            ...Changelog_textStyle,
            color: "#6b7280",
            fontSize: "12px",
            fontWeight: 600,
            lineHeight: "16px",
            marginTop: "8px",
          }}
        >
          {category}
        </Text>
        <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
      </Section>
      <Changelog_ChangelogCopy
        boxed={boxed}
        dark={boxed && accent}
        description={description}
        title={title}
      />
    </Column>
  );
  return (
    <Column className="changelog-content" style={{ verticalAlign: "top" }}>
      <Section style={{ width: "100%" }}>
        <Fragment>
          <Row>
            {right ? (
              <>
                {copy}
                <Column style={{ width: "16px" }}>&zwj;</Column>
                <Changelog_ChangelogRail accent={accent} muted={muted} />
              </>
            ) : (
              <>
                <Changelog_ChangelogRail accent={accent} muted={muted} />
                <Column style={{ width: "16px" }}>&zwj;</Column>
                {copy}
              </>
            )}
          </Row>
        </Fragment>
      </Section>
    </Column>
  );
};

const Changelog_ChangelogSection = ({
  category = "Refactoring",
  date = "19 Jan",
  description = "Introduced a new timeline pattern to clearly represent ordered states and progression, improving clarity across step-based and time-based flows.",
  layout = "line",
  title = "Refined layouts",
  variant = "muted-left",
  version = "v1.0.9",
}: Omit<Changelog_ChangelogProps, "theme">) => {
  const boxed = layout === "boxed";
  const right = variant.endsWith("-right");
  const muted = variant.startsWith("muted");
  const accent = variant.startsWith("accent");
  const meta = (
    <Changelog_ChangelogMeta
      category={category}
      date={date}
      muted={muted}
      right={right}
      version={version}
    />
  );
  const content = (
    <Changelog_ChangelogContent
      accent={accent}
      boxed={boxed}
      category={category}
      date={date}
      description={description}
      muted={muted}
      right={right}
      title={title}
      version={version}
    />
  );
  return (
    <Changelog_ChangelogShell>
      <Section style={{ width: "100%" }}>
        <Fragment>
          <Row>
            <Column style={{ padding: "0 24px" }}>
              <Section style={{ width: "100%" }}>
                <Fragment>
                  <Row>
                    {right ? content : meta}
                    <Column className="changelog-gap" style={{ width: "16px" }}>
                      &zwj;
                    </Column>
                    {right ? meta : content}
                  </Row>
                </Fragment>
              </Section>
            </Column>
          </Row>
        </Fragment>
      </Section>
    </Changelog_ChangelogShell>
  );
};

const Changelog_Changelog = ({
  theme = defaultTheme,
  ...props
}: Changelog_ChangelogProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Refined layouts</Preview>
    <EmailTailwind theme={theme}>
      <Body className="m-0">
        <Changelog_ChangelogSection {...props} />
      </Body>
    </EmailTailwind>
  </Html>
);

Changelog_Changelog.PreviewProps = {
  layout: "line",
  theme: defaultTheme,
  variant: "muted-left",
} satisfies Changelog_ChangelogProps;

const __Changelog = Changelog_Changelog;

type SplitTimeline_SplitCardsVariant =
  | "muted"
  | "muted-reverse"
  | "boxed"
  | "boxed-reverse"
  | "accent"
  | "accent-reverse"
  | "image-top"
  | "image-top-reverse"
  | "image-bottom"
  | "image-bottom-reverse";

interface SplitTimeline_SplitCardsProps {
  theme?: EmailTheme;
  variant?: SplitTimeline_SplitCardsVariant;
  index?: string;
  label?: string;
  date?: string;
  badge?: string;
  title?: string;
  description?: string;
  imageSrc?: string;
  imageAlt?: string;
}

const SplitTimeline_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const SplitTimeline_responsiveStyles = `
    @media only screen and (max-width: 599px) {
      .split-card-column { display: block !important; width: 100% !important; }
      .split-card-meta { display: table-header-group !important; width: 100% !important; }
      .split-card-copy { display: table-footer-group !important; width: 100% !important; }
      .split-card-mobile-space { display: block !important; line-height: 16px !important; }
    }
  `;

const SplitTimeline_textStyle = {
  fontFamily: SplitTimeline_fontFamily,
  margin: 0,
} as const;

const SplitTimeline_SplitShell = ({ children }: { children: ReactNode }) => (
  <>
    <style>{SplitTimeline_responsiveStyles}</style>
    <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: "#fffffe",
              maxWidth: "100%",
              width: "600px",
            }}
          >
            {children}
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  </>
);

const SplitTimeline_SplitMeta = ({
  index,
  label,
}: {
  index: string;
  label: string;
}) => (
  <Column
    className="split-card-column split-card-meta"
    style={{ padding: "16px 0", verticalAlign: "top", width: "112px" }}
  >
    <Section>
      <Text
        style={{
          ...SplitTimeline_textStyle,
          color: "#030712",
          fontSize: "60px",
          fontWeight: 600,
          lineHeight: 1,
        }}
      >
        {index}
      </Text>
      <Text
        style={{
          ...SplitTimeline_textStyle,
          color: "#9ca3af",
          fontSize: "12px",
          fontWeight: 600,
          lineHeight: "16px",
        }}
      >
        {label}
      </Text>
    </Section>
  </Column>
);

interface SplitTimeline_EventCardProps {
  badge: string;
  date: string;
  description: string;
  imageAlt: string;
  imageSrc: string;
  title: string;
  variant: SplitTimeline_SplitCardsVariant;
}

const SplitTimeline_EventCard = ({
  badge,
  date,
  description,
  imageAlt,
  imageSrc,
  title,
  variant,
}: SplitTimeline_EventCardProps) => {
  const muted = variant.startsWith("muted");
  const boxed = variant.startsWith("boxed");
  const accent = variant.startsWith("accent");
  const imageTop = variant.startsWith("image-top");
  const imageBottom = variant.startsWith("image-bottom");
  const dark = accent || imageTop || imageBottom;
  let cardBackgroundColor: string | undefined;
  if (dark) {
    cardBackgroundColor = "#030712";
  } else if (boxed) {
    cardBackgroundColor = "#f9fafb";
  }
  const image = (
    <Img
      alt={imageAlt}
      src={imageSrc}
      style={{
        borderRadius: "4px",
        maxWidth: "100%",
        verticalAlign: "middle",
      }}
      width="536"
    />
  );
  return (
    <Section style={{ width: "100%" }}>
      <Fragment>
        <Row>
          <Column
            style={{
              backgroundColor: cardBackgroundColor,
              borderRadius: muted ? undefined : "8px",
              padding: muted ? 0 : "16px",
            }}
          >
            {imageTop ? (
              <>
                {image}
                <Section style={{ lineHeight: "16px" }}>&zwj;</Section>
              </>
            ) : null}
            {(() => {
              if (muted) {
                return (
                  <Text
                    style={{
                      ...SplitTimeline_textStyle,
                      color: "#374151",
                      fontSize: "12px",
                      lineHeight: "16px",
                    }}
                  >
                    {date}
                  </Text>
                );
              }
              return (
                <Section style={{ width: "100%" }}>
                  <Fragment>
                    <Row>
                      <Column>
                        <Section>
                          <Fragment>
                            <Row>
                              <Column>
                                <Section
                                  style={{
                                    backgroundColor: "#6ee7b7",
                                    borderRadius: "9999px",
                                    height: "12px",
                                    lineHeight: accent ? "10px" : "12px",
                                    textAlign: "center",
                                    width: "12px",
                                  }}
                                >
                                  {accent ? (
                                    <Img
                                      alt=""
                                      src={emailAsset(
                                        "timelines/icon-check.png"
                                      )}
                                      style={{ marginBottom: "1px" }}
                                      width="8"
                                    />
                                  ) : (
                                    <>&zwj;</>
                                  )}
                                </Section>
                              </Column>
                              <Column style={{ width: "8px" }}>&zwj;</Column>
                              <Column>
                                <Text
                                  style={{
                                    ...SplitTimeline_textStyle,
                                    color: dark ? "#e5e7eb" : "#374151",
                                    fontSize: "12px",
                                    lineHeight: "16px",
                                  }}
                                >
                                  {date}
                                </Text>
                              </Column>
                            </Row>
                          </Fragment>
                        </Section>
                      </Column>
                      <Column style={{ textAlign: "right" }}>
                        <span
                          style={{
                            backgroundColor: "#eef2ff",
                            border: "1px solid #c7d2fe",
                            borderRadius: "9999px",
                            color: "#4f46e5",
                            display: "inline-block",
                            fontFamily: SplitTimeline_fontFamily,
                            fontSize: "12px",
                            fontWeight: 500,
                            lineHeight: "16px",
                            padding: "1px 8px",
